class Tutor {
  + name : string
  + email : string
  + bankAccount : string
}

class Student {
  + name : string
  + email : string
}

class Subject {
  + name : string
}

class TutoringOffer {
  + levelOfExpertise : string
  + hourlyPrice : float
}

class Availability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + level : string
  + targetDate : date
  + targetTime : time
}

class TutoringSession {
  + actualDate : date
  + actualTime : time
  + status : string
}

class Payment {
  + amount : float
  + method : string
}

